+//! Session-only GitHub access. Authorization is checked on the initiating machine;
+//! neither the remote transport nor its callers can request a credential.
+use eyre::{Result, bail};
+use std::collections::BTreeSet;
+
+#[derive(Clone, Debug, Default)]
+pub(crate) struct Scope {
+    repositories: BTreeSet<String>,
+    all: bool,
+}
+
+impl Scope {
+    pub(crate) fn from_flags(enabled: bool, repositories: &[String], all: bool) -> Result<Option<Self>> {
+        if !enabled {
+            if all || !repositories.is_empty() {
+                bail!("repository scope requires --github-relay-read-only");
+            }
+            return Ok(None);
+        }
+        if all == !repositories.is_empty() {
+            bail!("choose --github-relay-repo OWNER/REPO or --github-relay-all-repos, not both");
+        }
+        let repositories = repositories.iter().map(|repo| repository(repo)).collect::<Result<_>>()?;
+        Ok(Some(Self { repositories, all }))
+    }
+
+    fn permits(&self, repo: &str) -> bool {
+        self.all || self.repositories.contains(&repo.to_ascii_lowercase())
+    }
+}
+
+fn repository(value: &str) -> Result<String> {
+    let parts: Vec<_> = value.split('/').collect();
+    if parts.len() != 2 || parts.iter().any(|s| s.is_empty() || *s == "." || *s == ".."
+        || !s.bytes().all(|b| b.is_ascii_alphanumeric() || b"-_.".contains(&b))) {
+        bail!("expected a GitHub repository in OWNER/REPO form");
+    }
+    Ok(value.to_ascii_lowercase())
+}
+
+/// Expand only unambiguous shorthand, preserving paths and explicit transports.
+pub(crate) fn expand_repository(value: &str) -> Result<String> {
+    if value.contains(':') || value.starts_with(['/', '.', '~']) || std::path::Path::new(value).exists() {
+        return Ok(value.to_string());
+    }
+    repository(value)?;
+    Ok(format!("https://github.com/{}.git", value.trim_end_matches(".git")))
+}
+
+#[derive(Debug, PartialEq)]
+struct Target {
+    url: String,
+    git: bool,
+}
+
+fn authorize(scope: &Scope, method: &str, path: &str, query: Option<&str>) -> Result<Target> {
+    // Reject ambiguous encodings before URL parsing can normalize them.
+    if path.contains(['%', '\\']) || path.split('/').any(|s| s == "." || s == ".." || s.is_empty()) {
+        bail!("invalid relay path");
+    }
+    let p: Vec<_> = path.split('/').collect();
+    let (owner, repo) = match p.as_slice() {
+        ["api", "repos", owner, repo, ..] => (*owner, *repo),
+        ["git" | "web", owner, repo, ..] => (*owner, repo.trim_end_matches(".git")),
+        _ => bail!("unsupported GitHub operation"),
+    };
+    let name = repository(&format!("{owner}/{repo}"))?;
+    if !scope.permits(&name) { bail!("repository is outside the approved relay scope"); }
+    let git = p[0] == "git";
+    let allowed = match p.as_slice() {
+        ["git", _, _, "info", "refs"] => method == "GET" && query == Some("service=git-upload-pack"),
+        ["git", _, _, "git-upload-pack"] => method == "POST" && query.is_none(),
+        ["api", "repos", _, _] => method == "GET" || method == "HEAD",
+        ["api", "repos", _, _, kind, ..] => matches!(*kind, "contents" | "releases" | "tags" | "branches") && matches!(method, "GET" | "HEAD"),
+        ["api", "repos", _, _, "git", kind, ..] => matches!(*kind, "refs" | "matching-refs") && matches!(method, "GET" | "HEAD"),
+        ["web", _, _, "releases", "download", _, ..] => matches!(method, "GET" | "HEAD"),
+        _ => false,
+    };
+    if !allowed { bail!("GitHub relay permits read-only repository operations only"); }
+    if !git && let Some(query) = query {
+        for (key, _) in url::form_urlencoded::parse(query.as_bytes()) {
+            if !matches!(key.as_ref(), "ref" | "page" | "per_page") { bail!("unsupported query parameter"); }
+        }
+    }
+    let host = if p[0] == "api" { "api.github.com" } else { "github.com" };
+    let suffix = path.split_once('/').expect("validated path").1;
+    let mut url = format!("https://{host}/{suffix}");
+    if let Some(query) = query { url.push('?'); url.push_str(query); }
+    Ok(Target { url, git })
+}
