+#[cfg(unix)]
+pub(crate) mod unix {
+    use super::*;
+    use axum::{Router, body::{Body, to_bytes}, extract::{Request, State}, response::Response};
+    use reqwest::{Client, Method, Url};
+    use std::{path::{Path, PathBuf}, sync::Arc, time::Duration};
+    use tokio::{net::UnixListener, sync::Semaphore, task::JoinHandle};
+
+    #[derive(Clone)]
+    struct Broker { scope: Scope, client: Client, permits: Arc<Semaphore> }
+
+    pub(crate) struct Relay {
+        task: JoinHandle<()>,
+        directory: tempfile::TempDir,
+    }
+    impl Relay {
+        pub(crate) fn socket(&self) -> PathBuf { self.directory.path().join("relay.sock") }
+        pub(crate) async fn start(scope: Scope) -> Result<Self> {
+            if crate::github::resolve_token("github.com").is_none() {
+                bail!("no local GitHub credential found; sign in locally and inspect `mise token github`");
+            }
+            let directory = tempfile::tempdir()?;
+            let listener = UnixListener::bind(directory.path().join("relay.sock"))?;
+            let broker = Broker { scope, client: Client::builder().no_proxy()
+                .redirect(reqwest::redirect::Policy::none()).timeout(Duration::from_secs(300))
+                .connect_timeout(Duration::from_secs(15)).user_agent("mise-github-relay").build()?,
+                permits: Arc::new(Semaphore::new(8)) };
+            let task = tokio::spawn(async move {
+                let _ = axum::serve(listener, Router::new().fallback(handle).with_state(broker)).await;
+            });
+            Ok(Self { task, directory })
+        }
+    }
+    impl Drop for Relay { fn drop(&mut self) { self.task.abort(); } }
+
+    async fn handle(State(broker): State<Broker>, request: Request) -> Response {
+        match forward(broker, request).await {
+            Ok(response) => response,
+            // Deliberately never serialize upstream errors, URLs or credentials.
+            Err(_) => Response::builder().status(403).body(Body::from("GitHub relay request denied or unavailable")).expect("valid response"),
+        }
+    }
+
+    async fn forward(broker: Broker, request: Request) -> Result<Response> {
+        let permit = broker.permits.clone().try_acquire_owned()?;
+        let target = authorize(&broker.scope, request.method().as_str(),
+            request.uri().path().strip_prefix('/').unwrap_or_default(), request.uri().query())?;
+        let (parts, body) = request.into_parts();
+        let body = to_bytes(body, 8 * 1024 * 1024).await?;
+        if parts.method != Method::POST && !body.is_empty() { bail!("unexpected request body"); }
+        let (token, _) = crate::github::resolve_token("github.com").ok_or_else(|| eyre::eyre!("sign-in required"))?;
+        let mut req = broker.client.request(parts.method.clone(), &target.url);
+        if target.git { req = req.basic_auth("x-access-token", Some(token)); }
+        else { req = req.bearer_auth(token); }
+        for name in ["accept", "range", "git-protocol"] {
+            if let Some(value) = parts.headers.get(name) { req = req.header(name, value); }
+        }
+        if parts.method == Method::POST {
+            req = req.header("content-type", "application/x-git-upload-pack-request");
+        }
+        let mut response = req.body(body).send().await?;
+        // Only asset redirects are followed, without credentials or remote headers.
+        for _ in 0..3 {
+            if !response.status().is_redirection() { break; }
+            let location = response.headers().get("location").ok_or_else(|| eyre::eyre!("missing redirect"))?.to_str()?;
+            let url = Url::parse(location)?;
+            if target.git || !asset_redirect(&url) { bail!("unsupported redirect"); }
+            response = broker.client.request(parts.method.clone(), url).send().await?;
+        }
+        if response.status().is_redirection() { bail!("too many redirects"); }
+        let mut builder = Response::builder().status(response.status());
+        for name in ["content-type", "content-length", "content-range", "etag", "last-modified"] {
+            if let Some(value) = response.headers().get(name) { builder = builder.header(name, value); }
+        }
+        let stream = futures::stream::unfold((response, permit), |(mut response, permit)| async move {
+            match response.chunk().await {
+                Ok(Some(chunk)) => Some((Ok::<_, std::io::Error>(chunk), (response, permit))),
+                Ok(None) => None,
+                Err(_) => Some((Err(std::io::Error::other("relay transfer failed")), (response, permit))),
+            }
+        });
+        Ok(builder.body(Body::from_stream(stream))?)
+    }
+
+    fn asset_redirect(url: &Url) -> bool {
+        url.scheme() == "https" && url.username().is_empty() && url.password().is_none()
+            && url.port().is_none() && url.fragment().is_none()
+            && matches!(url.host_str(), Some("release-assets.githubusercontent.com" | "objects.githubusercontent.com"))
+    }
+
+    /// API adapter: an HTTP request over the forwarded private socket. No upstream
+    /// authentication headers are sent to the target or supplied by the target.
+    pub(crate) async fn request(socket: &Path, method: Method, url: &Url, headers: &http::HeaderMap) -> Result<reqwest::Response> {
+        let prefix = match url.host_str() {
+            Some("api.github.com") => "api", Some("github.com") => "web",
+            _ => bail!("unsupported relay host"),
+        };
+        let mut relay_url = Url::parse(&format!("http://localhost/{prefix}{}", url.path()))?;
+        relay_url.set_query(url.query());
+        let client = Client::builder().unix_socket(socket).no_proxy()
+            .redirect(reqwest::redirect::Policy::none()).timeout(Duration::from_secs(300)).build()?;
+        let mut req = client.request(method, relay_url);
+        for name in ["accept", "range"] {
+            if let Some(value) = headers.get(name) { req = req.header(name, value); }
+        }
+        req.send().await.map_err(|_| eyre::eyre!("GitHub relay disconnected or unavailable"))
+    }
+}
+
+#[cfg(test)]
+mod tests {
+    use super::*;
+    fn scope() -> Scope { Scope::from_flags(true, &["jdx/mise".into()], false).unwrap().unwrap() }
+    #[test]
+    fn scope_requires_explicit_choice() {
+        assert!(Scope::from_flags(true, &[], false).is_err());
+        assert!(Scope::from_flags(false, &[], true).is_err());
+        assert!(Scope::from_flags(true, &["jdx/mise".into()], true).is_err());
+        assert!(Scope::from_flags(true, &[], true).unwrap().unwrap().permits("other/private"));
+    }
+    #[test]
+    fn reads_only() {
+        for path in ["api/repos/jdx/mise", "api/repos/jdx/mise/releases/latest", "api/repos/jdx/mise/contents/Cargo.toml"] {
+            assert!(authorize(&scope(), "GET", path, None).is_ok());
+            assert!(authorize(&scope(), "POST", path, None).is_err());
+        }
+        assert!(authorize(&scope(), "POST", "git/jdx/mise.git/git-upload-pack", None).is_ok());
+        assert!(authorize(&scope(), "GET", "git/jdx/mise.git/info/refs", Some("service=git-upload-pack")).is_ok());
+        for path in ["api/repos/other/private", "api/user", "api/graphql", "api/repos/jdx/mise/../../user", "api/repos/jdx/mise/contents/%2e%2e", "git/jdx/mise.git/git-receive-pack"] {
+            assert!(authorize(&scope(), "GET", path, None).is_err(), "{path}");
+        }
+    }
+    #[test]
+    fn shorthand() {
+        assert_eq!(expand_repository("jdx/mise").unwrap(), "https://github.com/jdx/mise.git");
+        for value in ["./my/repo", "git@github.com:jdx/mise.git", "https://example.com/r.git", "/tmp/repo"] {
+            assert_eq!(expand_repository(value).unwrap(), value);
+        }
+        assert!(expand_repository("not/a/repository").is_err());
+    }
+}
