+use eyre::{Result, bail};
+use std::path::PathBuf;
+
+/// Open an SSH session, optionally borrowing read-only GitHub access
+#[derive(Debug, usage_rs::Args)]
+pub(crate) struct Ssh {
+    /// OpenSSH destination or SSH-config alias
+    destination: Option<String>,
+    /// SSH identity file
+    #[usage(long, short = 'i')]
+    identity_file: Option<PathBuf>,
+    /// SSH port
+    #[usage(long, short = 'p')]
+    port: Option<u16>,
+    /// OpenSSH option; repeat for multiple options
+    #[usage(long, short = 'o')]
+    ssh_option: Vec<String>,
+    /// Borrow read-only GitHub access for this session only
+    #[usage(long)]
+    github_relay_read_only: bool,
+    /// Approved GitHub repository; repeat to authorize more repositories
+    #[usage(long, value_name = "OWNER/REPO")]
+    github_relay_repo: Vec<String>,
+    /// Explicitly authorize reads of all repositories accessible locally
+    #[usage(long)]
+    github_relay_all_repos: bool,
+    /// Internal session adapter
+    #[usage(long, hide = true)]
+    relay_session: Option<PathBuf>,
+    /// Command to execute after --; omit for an interactive shell
+    #[usage(trailing_var_arg = true, allow_hyphen_values = true)]
+    command: Vec<String>,
+}
+
+impl Ssh {
+    pub(crate) async fn run(self) -> Result<()> {
+        let scope = crate::github_relay::Scope::from_flags(self.github_relay_read_only, &self.github_relay_repo, self.github_relay_all_repos)?;
+        if let Some(socket) = self.relay_session {
+            if scope.is_some() { bail!("cannot nest relay sessions"); }
+            #[cfg(unix)]
+            {
+                let mut command = self.command;
+                if let Some(first) = self.destination { command.insert(0, first); }
+                return crate::github_relay::unix::session(&socket, command).await;
+            }
+            #[cfg(not(unix))]
+            bail!("GitHub relay requires a POSIX target: {}", socket.display());
+        }
+        let destination = self.destination.ok_or_else(|| eyre::eyre!("an SSH destination is required"))?;
+        if let Some(scope) = scope {
+            #[cfg(unix)]
+            {
+                let mut host = crate::system::remote::ad_hoc_host(&destination, std::env::current_dir()?, &[])?;
+                host.port = self.port;
+                host.identity_file = self.identity_file;
+                host.ssh_options = self.ssh_option;
+                return crate::system::remote::ssh(&host, scope, &self.command).await;
+            }
+            #[cfg(not(unix))]
+            { let _ = scope; bail!("GitHub relay requires Linux or macOS"); }
+        }
+        let mut command = tokio::process::Command::new("ssh");
+        command.kill_on_drop(true);
+        if let Some(port) = self.port { command.args(["-p", &port.to_string()]); }
+        if let Some(identity) = self.identity_file { command.arg("-i").arg(identity); }
+        for option in self.ssh_option { command.args(["-o", &option]); }
+        command.arg("--").arg(destination);
+        if !self.command.is_empty() { command.arg(shell_words::join(&self.command)); }
+        let status = command.status().await?;
+        Err(crate::request_exit(status.code().unwrap_or(255)))
+    }
+}
