+}
+
+fn git(path: &Path, args: &[&str]) -> Result<String> {
+    let mut command = Command::new("git");
+    crate::git::sanitize_git_command(&mut command);
+    let output = command.arg("-C").arg(path).args(args).output()?;
+    if !output.status.success() { bail!("repository operation failed ({})", output.status); }
+    Ok(String::from_utf8(output.stdout)?.trim_end_matches('\n').to_string())
+}
+
+pub(crate) fn validate_origin(origin: &str) -> Result<()> {
+    if origin.starts_with('-') || origin.chars().any(char::is_control) { bail!("invalid repository origin"); }
+    if let Ok(url) = url::Url::parse(origin)
+        && (url.password().is_some() || (url.scheme() != "ssh" && !url.username().is_empty()) || url.query().is_some() || url.fragment().is_some())
+    { bail!("repository origin must not contain credentials, query parameters, or fragments"); }
+    Ok(())
+}
+
+impl Source {
+    pub(crate) fn fetch(origin: String) -> Result<Self> {
+        validate_origin(&origin)?;
+        let directory = tempfile::tempdir()?;
+        let repo = directory.path().join("repo");
+        let mut command = Command::new("git");
+        crate::git::sanitize_git_command(&mut command);
+        // No checkout: source templates and hooks are never evaluated locally.
+        let output = command.args(["clone", "--no-checkout", "--no-local", "--"])
+            .arg(&origin).arg(&repo).output()?;
+        if !output.status.success() { bail!("could not fetch setup repository using local Git authentication"); }
+        let revision = git(&repo, &["rev-parse", "HEAD"])?;
