+        Ok(Self { _directory: directory, bundle, revision, origin })
+    }
+}
+
+pub(crate) fn global_directory() -> PathBuf {
+    crate::env::MISE_GLOBAL_CONFIG_FILE.as_deref().and_then(Path::parent)
+        .unwrap_or(*crate::dirs::CONFIG).to_path_buf()
+}
+
+pub(crate) fn install(bundle: &Path, origin: &str, revision: &str, update: bool, yes: bool) -> Result<PathBuf> {
+    install_at(bundle, origin, revision, update, yes, &global_directory())
+}
+
+fn install_at(bundle: &Path, origin: &str, revision: &str, update: bool, yes: bool, destination: &Path) -> Result<PathBuf> {
+    validate_origin(origin)?;
+    if !matches!(revision.len(), 40 | 64) || !revision.bytes().all(|b| b.is_ascii_hexdigit()) { bail!("invalid pinned revision"); }
+    if destination.is_symlink() { bail!("global configuration directory must not be a symlink"); }
+    let parent = destination.parent().ok_or_else(|| eyre::eyre!("missing parent directory"))?;
+    std::fs::create_dir_all(parent)?;
+    let temporary = tempfile::tempdir_in(parent)?;
+    let checkout = temporary.path().join("checkout");
+    let output = Command::new("git").args(["clone", "--no-checkout", "--"]).arg(bundle).arg(&checkout).output()?;
+    if !output.status.success() { bail!("invalid transferred repository bundle"); }
+    if git(&checkout, &["rev-parse", "HEAD"])? != revision { bail!("transferred revision mismatch"); }
+    let entries = git(&checkout, &["ls-tree", "-rz", "--name-only", revision])?;
+    for entry in entries.split('\0').filter(|s| !s.is_empty()) {
+        let path = Path::new(entry);
+        if path.components().any(|c| !matches!(c, std::path::Component::Normal(_)))
+            || entry.split('/').any(|p| p.eq_ignore_ascii_case(".git"))
+        { bail!("unsafe source repository path"); }
+        if entry.ends_with(".local.toml") { bail!("source contains machine-local configuration ({entry}); remove it from the repository before onboarding"); }
+    }
+    git(&checkout, &["remote", "set-url", "origin", origin])?;
