+            git(destination, &["merge-base", "--is-ancestor", "HEAD", revision])?;
+            git(destination, &["-c", "core.hooksPath=/dev/null", "merge", "--ff-only", revision])?;
+        }
+        return Ok(destination.to_path_buf());
+    }
+    let nonempty = destination.exists() && destination.read_dir()?.next().is_some();
+    if nonempty {
