+            }
+        }
+        std::fs::rename(checkout.join(".git"), destination.join(".git"))?;
+    } else {
+        if destination.exists() { std::fs::remove_dir(destination)?; }
+        std::fs::rename(checkout, destination)?;
+    }
+    Ok(destination.to_path_buf())
